/*!
 * Missivus — send Matomo email through the Microsoft Graph API.
 * @license https://www.gnu.org/licenses/gpl-3.0.html GPL v3 or later
 *
 * This file is hand-written rather than produced by `./console vue:build`, so that a single button
 * does not make Matomo's whole Node toolchain a prerequisite for installing the plugin. The UMD
 * wrapper is the same shape Matomo's own plugin bundles use, and the equivalent source lives in
 * ../src — running `./console vue:build Missivus` on a development install regenerates this file.
 */
(function (root, factory) {
  if (typeof exports === 'object' && typeof module === 'object') {
    module.exports = factory(require('CoreHome'), require('vue'));
  } else if (typeof define === 'function' && define.amd) {
    define(['CoreHome', 'vue'], factory);
  } else if (typeof exports === 'object') {
    exports['Missivus'] = factory(require('CoreHome'), require('vue'));
  } else {
    root['Missivus'] = factory(root['CoreHome'], root['Vue']);
  }
})(typeof self !== 'undefined' ? self : this, function (CoreHome, Vue) {
  'use strict';

  var h = Vue.h;
  var translate = CoreHome.translate;
  var AjaxHelper = CoreHome.AjaxHelper;

  var SendTestEmail = {
    name: 'SendTestEmail',

    // Matomo passes the field's value in and expects updates back out. This control stores
    // nothing, so modelValue is accepted and ignored.
    props: {
      modelValue: { type: String, default: '' }
    },

    emits: ['update:modelValue'],

    data: function () {
      return {
        recipient: '',
        sending: false,
        ready: false,
        reason: '',
        result: null
      };
    },

    mounted: function () {
      this.refreshStatus();

      if (window.$) {
        window.$(document).on('ajaxComplete.missivus', this.onAjaxComplete);
      }
    },

    unmounted: function () {
      if (window.$) {
        window.$(document).off('ajaxComplete.missivus');
      }
    },

    methods: {
      // Only a settings save can change the answer, and matching on it also keeps this from
      // reacting to the status request it triggers itself.
      onAjaxComplete: function (event, xhr, settings) {
        var url = (settings && settings.url) || '';
        var data = (settings && typeof settings.data === 'string') ? settings.data : '';

        if ((url + data).indexOf('setSystemSettings') !== -1) {
          this.refreshStatus();
        }
      },

      // The test sends with the SAVED settings, so the button is only enabled once the stored
      // configuration could actually send. Otherwise the first thing a new operator sees is a
      // failure caused by not having clicked Save.
      refreshStatus: function () {
        var self = this;

        AjaxHelper.fetch({
          method: 'Missivus.getTestEmailStatus'
        }).then(function (response) {
          self.ready = !!(response && response.ready);
          self.reason = (response && response.reason) ? response.reason : '';
        }).catch(function () {
          self.ready = false;
          self.reason = translate('Missivus_TestEmailNotReady');
        });
      },

      send: function () {
        var self = this;

        if (this.sending || !this.ready) {
          return;
        }

        this.sending = true;
        this.result = null;

        AjaxHelper.post({
          method: 'Missivus.sendTestEmail'
        }, {
          to: this.recipient
        }).then(function (response) {
          var success = !!(response && response.success);

          self.result = {
            success: success,
            message: (response && response.message)
              ? response.message
              : translate(success ? 'Missivus_TestEmailSent' : 'Missivus_TestEmailFailed')
          };
        }).catch(function (error) {
          self.result = {
            success: false,
            message: (error && error.message)
              ? error.message
              : translate('Missivus_TestEmailFailed')
          };
        }).then(function () {
          self.sending = false;
        });
      },

      onRecipientInput: function (event) {
        this.recipient = event.target.value;
      },

      onClick: function (event) {
        event.preventDefault();
        this.send();
      }
    },

    render: function () {
      var disabled = this.sending || !this.ready;

      var children = [
        h('div', { class: 'missivusTestEmailRow' }, [
          h('input', {
            type: 'email',
            class: 'missivusTestEmailRecipient',
            placeholder: translate('Missivus_TestEmailRecipientLabel'),
            value: this.recipient,
            disabled: disabled,
            onInput: this.onRecipientInput
          }),
          h('button', {
            type: 'button',
            class: 'btn',
            disabled: disabled,
            onClick: this.onClick
          }, this.sending
            ? translate('Missivus_SendingTestEmail')
            : translate('Missivus_SendTestEmail'))
        ])
      ];

      // Matomo's own notification classes, so both boxes stay readable in the dark theme and pick
      // up any future restyling of notifications for free.
      if (!this.ready && this.reason) {
        children.push(h('div', {
          class: 'notification system notification-info missivusTestEmailResult'
        }, this.reason));
      }

      if (this.result) {
        children.push(h('div', {
          class: 'notification system missivusTestEmailResult '
            + (this.result.success ? 'notification-success' : 'notification-error')
        }, this.result.message));
      }

      return h('div', { class: 'missivusTestEmail' }, children);
    }
  };

  return {
    SendTestEmail: SendTestEmail
  };
});
